select public.prepify_load_bank('Computer Science', 3, $j$[["In a professional development team, the person responsible for creating the \"Graphical User Interface (GUI)\" is known as the:",["Front-end Developer.","Back-end Developer.","Database Administrator.","Network Engineer."],"A",3,0,"c8a1e74f71a8",0],["What is the functional difference between the starting tag <tag> and the ending tag in HTML?",["The ending tag uses a backslash \\.","The ending tag is recognized with the help of a forward slash /.","The starting tag must be in capital letters.","There is no difference between them."],"B",3,0,"2518f5e96114",0],["What is the official file extension required for a browser to recognize a document as an HTML file?",["txt","doc","html","web"],"C",3,0,"149773867ac3",0],["Where must all the \"main constituents\" of an HTML document be arranged?",["Inside the <head> tag-pair.","Inside the <body> tag-pair.","Before the <html> tag.","Inside the title section."],"B",3,0,"a715f7ff07af",0],["What is the functional difference between <span> and <div> in text arrangement?",["Span provides style to a single line; Div provides it to a set of lines.","Div is for images; Span is for text.","Span is for the header; Div is for the footer.","There is no difference; they are interchangeable."],"A",3,0,"1a62e7848755",0],["Which tag-pair should be used if you want to emphasize a word specifically with \"italics\" as a note?",["<b>","<i>","<u>","<sub>"],"B",3,0,"3d3df46bd5bd",0],["In the text \"Strong character,\" which tag-pair is officially used for the display of \"bold and strong characters\"?",["<em>","<small>","<strong>","<sup>"],"C",3,0,"1db447853593",0],["If a developer wants a heading that is \"largest and most important,\" which level should they choose?",["Level 1 (h1)","Level 6 (h6)","Level 10 (h10)","Main Level (h0)"],"A",3,1,"4ec49e071ef5",0],["According to the DOM tree hierarchy, what does the 'html' node contain?",["Only the images of the site.","Two sub-nodes: 'head' and 'body'.","The web browser's search engine index.","The password for the CRM system."],"B",3,0,"16d289cc6003",0],["Which IDE environment is mentioned as being used for the \"Visual Studio version 2022\" examples in the text?",["Netbeans","Microsoft Visual Studio","Notepad","Canva"],"B",3,0,"5c8c19ed5168",0],["How many languages can the Microsoft Visual Studio IDE support for writing and running code?",["Only 1 (HTML)","Exactly 10","More than 30","Exactly 100"],"C",3,0,"517693460d1d",0],["A developer wants to organize data using bullets of type \"circle\" or \"square.\" Which tag-pair must be used as the parent container?",["<ul>","<ol>","<li>","<dl>"],"A",3,0,"055ace91f1d0",0],["In a professional HTML table, which tag-pair is specifically designated to allocate and designate data within a \"Header Row\"?",["<td>","<tr>","<th>","<table>"],"C",3,0,"59354b0aaef6",0],["Why is JavaScript considered an ideal language for making webpages dynamic at the \"client-end\"?",["It requires a very high amount of memory to run.","It does not consume much memory and works on any operating system.","It can only be used on Windows-based servers.","It replaces the need for using any HTML tags."],"B",3,0,"a8a5328d68b4",0],["In programming, what is the official term for a user action that can be \"sensed\" and triggers a specific task to be done?",["Script","event","Variable","Function"],"B",3,1,"ae07983582fb",0],["Which JavaScript function is used to display a notification or message box to inform the user about the result of an action?",["alert()","prompt()","document.write()","console.log()"],"A",3,1,"0db63671aa9a",0],["Which JavaScript function allows the program to take input from the user via a message window?",["alert()","prompt()","document.write()","var()"],"B",3,1,"ecd7ce965e64",0],["Which JavaScript operator is used when you specifically need the \"remainder\" of a division operation?",["/ (Division)","% (Modulus)","* (Multiplication)","+ (Addition)"],"B",3,0,"c8978f8a2222",0],["What is the purpose of the comparison operator != in a selection statement?",["To check if two values are equal.","To check if two values are not equal.","To check if the left value is greater.","To check if the right value is smaller."],"B",3,0,"9a9b2a7cd8a1",0],["In a selection scenario where there are \"more than two possibilities,\" which structure should be used to extend the logic?",["if statement","if-else statement","if-else if-else statement","For Loop"],"C",3,0,"ef48c42d5189",0],["What is the primary advantage of using an \"Iterative Statement\" like a For Loop?",["It makes the code more difficult to read.","The same task is achieved in much lesser lines of code.","It prevents the computer from using any memory.","It only works for mathematical calculations."],"B",3,0,"b575f3fd6a0a",0],["In a For Loop, which three components must be set to control the number of iterations?",["Start, Stop, and Pause.","Initialization, terminating condition, and step-size.","HTML, CSS, and JS.","Input, Process, and Output."],"B",3,0,"cf5ec054470a",0],["What is the starting \"index number\" for any array declared in JavaScript?",["0","1","-1","10"],"A",3,0,"b5bd5bd70780",0],["Which debugging command allows a programmer to trace the code \"line by line\"?",["Start Debugging","Step Into","Toggle Breakpoint","Restart"],"B",3,1,"2b6d89fbb4f9",0],["When a programmer wants to add a note in the code that is \"not part of the output\" and is \"ignored by the browser,\" they use:",["Tags","comments","Breakpoints","Alerts"],"B",3,1,"18806fb6eab4",0],["According to the DOM tree hierarchy, which node is located at the \"absolute top\" for a whole webpage?",["Document","html","head","body"],"A",3,0,"d37b9db6c850",0],["Which of the following is the correct order of priority of CSS styles if all three are used in a webpage?",["External CSS → Embedded CSS → Inline CSS","Embedded CSS → External CSS → Inline CSS","Inline CSS → Embedded CSS → External CSS","Embedded CSS → Inline CSS → External CSS"],"C",3,0,"172405c818b3",0],["Which CSS method is recommended for large projects?",["Inline CSS","Embedded CSS","External CSS","Internal CSS"],"C",3,0,"8789e235353c",0],["If a user is unable to recall the specific URL of a webpage, which tool creates \"different combinations\" based on keywords to locate it?",["Web Browser","Search Engine","Web Hosting Service","Hyper-Text Markup Language"],"B",3,1,"6af60d958f35",0],["What is the first step to establishing a digital presence?",["Website Development","Visual Studio Installation","Writing JavaScript","Buying a Web Server"],"A",3,0,"ca34b3300cd8",0],["What is a website called if the information is changed or adjusted in accordance with user input or choice?",["Static Website","Dynamic Website","Single Page Website","Offline Website"],"B",3,0,"fc9aaa3168ff",0],["Which of these can be declared as a valid JavaScript variable name without a naming error?",["2myVariable","my-variable","my_variable","my variable"],"C",3,0,"97f76a642af4",0],["The value of a variable can change while a program runs, whereas the value of a constant:",["can only be changed by special functions","remains the same throughout the program","changes automatically with the data type","can be changed once per minute"],"B",1,0,"f16e45cb1a99",0],["What is the output of document.write(15 % 4) in JavaScript?",["3.75","4","3","1"],"C",5,0,"6e98b004d157",0],["Giving a single name to a collection of related elements of the same data type is called:",["An array","A function","A loop","A variable"],"A",1,0,"b92c91174383",0],["Which of these JavaScript operators is NOT a logical operator?",["&&","||","!","+"],"D",3,0,"bba836b36c01",0],["What happens when the condition of an if statement is valid but evaluates to false?",["The program terminates immediately","Control passes to the statement right after the if block","The condition is evaluated forever","A syntax error stops the program"],"B",5,0,"f0017cf3da89",0],["A web developer wants a video to work in as many browsers as possible. Which video format should be preferred?",["AVI","MOV","MP4","WMV"],"C",3,1,"a7cb8a5e003d",0],["What is the purpose of the return statement inside a JavaScript function?",["To stop the whole program","To print text on the screen","To send a value back to the caller","To declare a new variable"],"C",3,0,"7723e867ac4b",0],["A page contains <p id=\"intro\">Hello</p>. Which JavaScript statement correctly reaches this paragraph through the DOM?",["document.getElement(\"intro\")","document.getElementById(\"intro\")","document.id(\"intro\")","document.findById(\"intro\")"],"B",3,1,"4444655a463a",0],["In the HTML page <html><head><title>My Page</title></head><body><h1>Welcome</h1></body></html>, the parent of the <title> element in the DOM tree is:",["<html>","<body>","<head>","<h1>"],"C",5,0,"31265308ffb8",0],["Which software development activity focuses on locating and correcting errors after a program has been written?",["Writing the code for the first time","Debugging","Designing the user interface","Translating the program into machine language"],"B",1,0,"bde8534ce3a8",0],["A program runs without syntax errors but produces the wrong output. This is most likely a:",["Compilation error","Logical error","Typing error","Installation error"],"B",3,1,"7e69692fa844",0],["How many times does the loop for (let i = 0; i < 3; i++) run?",["0","2","3","4"],"C",5,0,"fda711a785a2",0],["A student writes two sentences on separate lines in the HTML body without any tag between them. How will the page most likely display them?",["On separate lines","As a browser error","On the same line","With the second sentence hidden"],"C",5,1,"64918e1c2acf",0],["Which JavaScript data type is designed to hold the result of a logical expression?",["Integer","String","Float","Boolean"],"D",1,0,"bb1624748319",0],["Although HTML uses tags and elements, its main purpose is to:",["Perform arithmetic calculations","Define the structure and content of web pages","Store records in a database","Run loops and conditions"],"B",3,0,"ec33165380ad",0],["Which CSS property changes the background colour of an element?",["color","bgcolor","background-color","text-color"],"C",1,0,"1bd3221f47af",0],["Which JavaScript method writes text directly into the HTML document?",["console.log()","alert()","document.write()","prompt()"],"C",1,0,"333343382470",0],["A ticket counter charges 50 if the user's age is 60 or above, and 100 otherwise. Which programming structure suits this logic best?",["A loop","An if-else decision","An array","A sequential structure"],"B",3,1,"cc1d6cdb3ffb",0],["A school admits children who are at least 4 years old using the code: var kid_age = 4; if (kid_age > 4) { document.write(\"Admission Granted\"); }. What happens when kid_age is 4?",["\"Admission Granted\" is printed","Nothing is printed","An error occurs because else is missing","\"Admission Granted\" is printed twice"],"B",5,1,"c4af6131f557",0],["A program prints \"Excellent\" if score > 80, else \"Good\" if score > 60. A student scores 75. What is printed?",["Excellent","Good","Nothing","Error"],"B",3,1,"7b8c9a57eb2e",0],["A shopping list is stored as cart = ['Book', 'Pen', 'Eraser']. How is the second item (\"Pen\") accessed?",["cart[1]","cart[2]","cart(\"Pen\")","cart[0]"],"A",5,1,"cbbd1dc24b4f",0],["A student wants to display the numbers 1 to 100 on the screen. Which statement is most efficient for this repetitive task?",["if statement","do...while loop","for loop","switch statement"],"C",3,1,"3c7da4cc84a4",0],["In function add(a, b) { return a + b; }, what are a and b called?",["Return values","Parameters","Arrays","Strings"],"B",3,0,"f05c807cb3fe",0],["In <p> Hello World </p>, what is the role of p?",["Attribute","Tag","Property","Variable"],"B",1,0,"f469b03ff6d0",0],["To make all text inside <div id=\"main\">Text</div> blue, which CSS selector targets this div?",[".main","#main","div.main","*main"],"B",3,1,"21964910cc16",0],["A traffic-light program sets light = \"Green\" and then checks if (light == \"Red\") to print \"Stop\". What happens?",["It prints \"Go\"","It prints \"Stop\"","It prints \"Wait\"","It does nothing"],"D",3,1,"36a66e362ef8",0],["A program writes average = sum / totalNumbers to find the average of three numbers. This line represents which programming concept?",["Input","Output","Processing","Conditional"],"C",3,1,"83b555d2fe85",0],["Your JavaScript runs without any error message but gives a wrong calculation result. What type of error is this?",["Syntax error","Logical error","Reference error","Compilation error"],"B",3,1,"972df260b4a6",0],["A page uses <video width=\"500px\" height=\"500px\"><source src=\"video.mp4\" type=\"video/mp4\"></video>. The video shows, but the user cannot pause it or change the volume. What is the most likely reason?",["The width and height are too large","The controls attribute is missing from the <video> tag","The source tag should be outside the <video> tag","The file should be .avi"],"B",5,1,"ab6d9e2e29ab",0],["How many times does the loop for (let i = 1; i <= 5; i++) run?",["4","5","6","1"],"B",5,0,"fda711a785a2",0],["How many times does the loop for (let i = 0; i < 10; i += 2) run?",["4","5","10","6"],"B",5,0,"fda711a785a2",0],["In the JavaScript array let colours = [\"red\", \"green\", \"blue\"];, the value of colours[1] is:",["\"red\"","\"green\"","\"blue\"","undefined"],"B",5,0,"b5bd5bd70780",0],["A shop uses the code: var amount = 500; if (amount >= 500) { document.write(\"Discount!\"); }. What happens?",["\"Discount!\" is printed","Nothing is printed","An error occurs","\"500\" is printed"],"A",5,1,"c4af6131f557",0],["What is the value of 17 % 5 in JavaScript?",["3","2","3.4","12"],"B",5,0,"c8978f8a2222",0],["Which JavaScript function shows a dialog box with a text field so that the user can type a value?",["alert()","confirm()","prompt()","document.write()"],"C",3,0,"ecd7ce965e64",0],["To show a message inside the web page itself rather than in a pop-up, a beginner can use:",["alert()","document.write()","prompt()","confirm()"],"B",3,0,"333343382470",0],["Which HTML heading tag displays the smallest heading?",["<h1>","<h3>","<h6>","<h10>"],"C",3,0,"4ec49e071ef5",0],["A program must print \"A\", \"B\", \"C\" or \"Fail\" depending on a student's marks. Which structure is most suitable?",["A single if statement","An if-else statement","An if-else if-else statement","A for loop"],"C",3,1,"ef48c42d5189",0],["Given function square(n) { return n * n; }, what does square(4) send back to the caller?",["8","16","4","Nothing"],"B",5,0,"7723e867ac4b",0],["In the page <html><head><title>Home</title></head><body><p>Hi</p></body></html>, the parent of the <p> element is:",["<html>","<head>","<body>","<title>"],"C",5,0,"31265308ffb8",0],["A news website shows each reader different stories based on the reader's choices. This kind of website is:",["static","dynamic","offline","read-only"],"B",3,1,"fc9aaa3168ff",0],["Finding and fixing the mistakes in a program after it has been written is called:",["compiling","debugging","designing","uploading"],"B",1,0,"bde8534ce3a8",0]]$j$::jsonb, true);
